<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungen</title><style>body{font:13px Arial;background:#d9d9d9;padding:12px}.window{max-width:1400px;margin:auto;background:#efefef;border:1px solid #888;padding:14px}.button{display:inline-block;padding:7px 12px;border:1px solid #777;background:#eee;color:#111;text-decoration:none}table{width:100%;border-collapse:collapse;background:#fff;margin-top:12px}th,td{border:1px solid #aaa;padding:6px;vertical-align:top}th{background:#ddd}.money{text-align:right;white-space:nowrap}.filters{display:flex;gap:8px;flex-wrap:wrap}input,select{padding:6px}.open{background:#fff8e1}</style></head><body><div class="window"><div style="text-align:right"><a href="{{ route('frontend.switch','modern') }}">Zum neuen Frontend wechseln →</a></div><h2>Rechnungen</h2><form class="filters" method="get"><input name="q" value="{{ request('q') }}" placeholder="Rechnung, Auftrag, Kunde"><select name="status"><option value="all" @selected($status==='all')>Alle</option><option value="open" @selected($status==='open')>Offen</option><option value="paid" @selected($status==='paid')>Bezahlt</option></select><button class="button">Filtern</button></form>@if($rechnungen->isEmpty())<p>Keine Rechnungen gefunden.</p>@else<table><thead><tr><th>Rechnung</th><th>Datum</th><th>Fällig</th><th>Kunde</th><th>Auftrag</th><th>Betrag</th><th>Bezahlt</th><th>Status</th><th>Mahnstufe</th></tr></thead><tbody>@foreach($rechnungen as $r)<tr @class(['open'=>(int)$r->boolBezahlt===0])><td><a href="{{ route('rechnungen.show',$r->intID) }}">{{ $r->intRechNr }}</a></td><td>{{ date('d.m.Y',strtotime($r->datRechnungsDatum)) }}</td><td>{{ date('d.m.Y',strtotime($r->datFaelligkeitsDatum)) }}</td><td>{{ $kunden[$r->intKID]->strName ?? $r->strKundenNameAufRechnung }}</td><td><a href="{{ route('kunden.auftraege.show',[$r->intKID,$r->intAufNr]) }}">{{ $r->intAufNr }}</a></td><td class="money">{{ number_format((float)$r->fRechnungsbetrag,2,',','.') }} €</td><td class="money">{{ number_format((float)$r->fBezahlterBetrag,2,',','.') }} €</td><td>{{ $r->boolBezahlt ? 'Bezahlt' : 'Offen' }}@if($r->bolRechnungStrittig) · Strittig @endif</td><td>{{ $r->intMahnstufe ?? '-' }}</td></tr>@endforeach</tbody></table>{{ $rechnungen->links() }}@endif</div><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>